class FastaError(Exception):
    """Raised when FASTA input is malformed."""

    def __init__(self, message, line_number=None):
        if line_number is not None:
            message = f"{message} (line {line_number})"
        super().__init__(message)
        self.message = message
        self.line_number = line_number


def parse_fasta(path):
    """Parse a FASTA file, yielding (header, sequence) tuples.

    Raises:
        FastaError: on malformed input:
            - sequence data before any header line
            - empty header ('>' alone)
            - duplicate headers
            - invalid characters in sequence lines
    """
    header = None
    chunks = []
    seen = set()

    def flush(line_number):
        if header is None:
            raise FastaError(
                "sequence data before any header line", line_number
            )

    with open(path, "r", encoding="utf-8") as fh:
        for lineno, raw in enumerate(fh, start=1):
            line = raw.strip()
            if not line:
                continue
            if line.startswith(">"):
                # finalize previous record
                if header is not None:
                    yield header, "".join(chunks)
                    chunks = []
                name = line[1:].strip()
                if not name:
                    raise FastaError("empty header", lineno)
                if name in seen:
                    raise FastaError(f"duplicate header '{name}'", lineno)
                seen.add(name)
                header = name
            else:
                if header is None:
                    raise FastaError(
                        "sequence data before any header line", lineno
                    )
                bad = set(line.upper()) - set("ACGTN")
                if bad:
                    raise FastaError(
                        f"invalid character(s) {''.join(sorted(bad))!r} "
                        f"in sequence",
                        lineno,
                    )
                chunks.append(line)

    # final record
    if header is not None:
        yield header, "".join(chunks)
